  "elem_tab_l2tp_19": "<strong data-i18n=\\",
  "elem_tab_mtproto_20": "Поддельный прокси-сервер с защитой от фильтрации TLS Telegram с официальной поддержкой спонсорских каналов (<span style=\\",
