  "elem_tab_ssl_58": "Если вы мигрировали с маршрутизатора Mikrotik на этот сервер, введите сертификат <strong>Root CA</strong>, сертификат сервера и закрытый ключ в полях ниже. При этом цифровая идентичность сервера точно сохраняется, и все ваши предыдущие пользователи и клиенты (например, в <strong data-i18n=\\",
