  "در روش‌های قدیمی (مانند تروجان یا VLESS سنتی)، مدیر سرور باید یک دامنه اختصاصی ثبت می‌کرد. فیلترینگ به سادگی با بررسی فیلد SNI در بسته TLS ClientHello، دامنه را در لیست سیاه قرار می‌داد و سرور بلااستفاده می‌شد.": "In legacy methods (like Trojan or traditional VLESS), admins had to register custom domains. DPI easily blacklisted domains by inspecting SNI in TLS ClientHello, rendering servers unusable.",
  "در ساعات اوج مصرف اینترنت در ایران، اپراتورها روی اتصالات خارجی پکت‌لاست‌های ساختگی (۲۰٪ تا ۶۰٪) اعمال می‌کنند. پروتکل‌های سنتی مبتنی بر TCP به محض دیدن افت بسته سرعت خود را به شدت کاهش می‌دهند.": "During peak hours in Iran, operators impose artificial packet loss (20% to 60%) on international connections. Traditional TCP protocols sharply throttle speeds upon detecting lost packets.",
