  "سرقت زنده گواهینامه معتبر:": "Live Theft of Valid Certificate:",
  "سرور شما نیازی به داشتن گواهینامه ندارد؛ در هندشیک، گواهی واقعی و ۱۰۰٪ قانونی سایت مقصد (مثلاً گوگل یا مایکروسافت) را استراق کرده و ارائه می‌دهد.": "Your server needs no certificate; during handshake, it steals and presents the 100% genuine certificate of target site (e.g. Google or Microsoft).",
