  "عبور از فیلترینگ آی‌پی و پورت با استفاده از شبکه ابری Cloudflare CDN و گواهینامه معتبر SSL": "Bypass IP and port blocking using Cloudflare CDN and valid SSL certificate",
  "عبور از فیلترینگ شدید DPI با شبیه‌سازی کامل یک وب‌سایت بزرگ خارجی بدون نیاز به خرید دامنه یا سرتیفیکیت SSL.": "Bypass strict DPI filtering via full simulation of major external website without buying domains or SSL certificates.",
