  "عدم نیاز به تعریف دو پورت مجزا برای اپلیکیشن‌ها و تلگرام/مرورگر.": "No need to define two separate ports for apps and Telegram/browser.",
  "عدم نیاز به دامنه/گواهی، شبیه‌سازی ۱۰۰٪ بسته‌های TLS، مصونیت مطلق در برابر اسکنرهای فعال (Active Probing)، و حل مشکل TLS-in-TLS با فلو Vision.": "No domain/cert required, 100% TLS packet simulation, absolute immunity against active probing, and eliminates TLS-in-TLS with Vision flow.",
