  "🎮 اگر کاربران شکایت از پینگ و قطعی تماس صوتی دارند:": "🎮 If users complain about ping or voice call drops:",
  "در صورتی که گواهینامه معتبر SSL (مانند Let": "When using a valid SSL certificate (like Let's Encrypt)",
  "🔒 تفاوت گواهینامه معتبر رسمی Let": "🔒 Difference Between Official Let's Encrypt Cert & Self-Signed",
  "💡 کلید تولیدشده تصادفی ۱۶ یا ۳۲ بایتی در فرمت استاندارد Base64.": "💡 Randomly generated 16 or 32-byte key in standard Base64 format.",
  "💡 در پروتکل تروجان هش SHA-224 این پسورد در اولین بسته اتصال ارسال می‌شود؛ ظاهر ترافیک ۱۰۰٪ شبیه HTTPS وب است.": "💡 In Trojan, SHA-224 hash of this password is sent in first packet; traffic appearance is 100% identical to web HTTPS.",
  "برای این پروتکل تنظیم دستی پیش‌فرض فعال است.": "Default manual configuration is active for this protocol.",
  "سناریوی ایده‌آل:": "Ideal Scenario:",
  "💡 نرخ دانلود Brutal که به پکت‌لاست‌های ۳۰٪ تا ۵۰٪ توجهی نکرده و با حداکثر سرعت فایل دریافت می‌کند.": "💡 Brutal download rate that ignores 30% to 50% packet loss and downloads files at maximum line capacity.",
  "💡 الگوریتم BBR پهنای باند را در حضور پکت‌لاست به حداکثر رسانده و جیتر (Jitter) پینگ را به صفر نزدیک می‌کند.": "💡 BBR algorithm maximizes throughput under packet loss and minimizes ping jitter close to zero.",
