  "ترافیک کاملاً منطبق بر وب‌سایت امن HTTPS واقعی با گواهینامه معتبر Let's Encrypt": "Traffic strictly conforms to a genuine HTTPS website with a valid Let's Encrypt certificate",
  "ترانسپورت شبکه مشخص می‌کند داده‌ها در لایه انتقال با چه ساختاری بسته‌بندی شوند. انتخاب ترانسپورت مستقیماً روی پینگ، مصرف باتری، و امکان پنهان‌سازی پشت شبکه‌های CDN تاثیرگذار است.": "Network transport defines how packets are framed at the transport layer. Transport selection directly influences ping latency, battery usage, and ability to disguise traffic behind CDN networks.",
  "تروجان به جای ساختن یک پروتکل اختصاصی، مستقیماً ترافیک مرورگرهای وب را شبیه‌سازی می‌کند.": "Trojan simulates real web browser traffic directly rather than inventing a custom protocol.",
