  "ثابت / دستی": "Static / Manual",
  "جایگزین جدید و بسیار بهینه‌تر از WebSocket در نسخه‌های جدید Sing-box؛ سربار هدرهای سنتی وب‌سوکت را حذف کرده و در ارتباطات ابری پینگ را ۲۰ الی ۳۰ میلی‌ثانیه کاهش می‌دهد.": "A new, highly optimized alternative to WebSocket in modern Sing-box; eliminates legacy WebSocket header overhead and reduces cloud latency by 20 to 30ms.",
  "جایگزین نوین و بهینه‌تر از WebSocket در Sing-box؛ سربار هدرهای دست‌وپاگیر وب‌سوکت را حذف کرده و تا ۳۰ میلی‌ثانیه پینگ بهتری ارائه می‌دهد.": "Modern, optimized alternative to WebSocket in Sing-box; eliminates cumbersome WebSocket headers and offers up to 30ms improved ping.",
