  "کاربر جدید و تولید کانفیگ‌ها در هسته...": "new users and generating configs in core...",
  "در روش‌های سنتی، قرار دادن یک دامنه مجاز (مانند سایت بانک یا دامنه شاد) در SNI باعث خطای عدم تطابق گواهینامه SSL و شناسایی با اسکنرهای فعال (Active Probing) می‌شد. تکنولوژی": "In traditional methods, placing an allowed domain (such as a bank site or internal portal) in SNI caused SSL certificate mismatch errors and detection by active probes. The technology",
  "در زمان ملی شدن یا قطعی اینترنت، هیستریا ۲ را روی پورت‌های خلوت مانند": "During severe censorship or national intranet shutdowns, set Hysteria 2 on quiet ports like",
  "در صورتی که گواهینامه معتبر SSL (مانند Let's Encrypt پنل) روی پورت ۴۴۳ فعال باشد، فیلترینگ ارتباط را به عنوان یک بازدید طبیعی از وبسایت اینترنتی قلمداد می‌کند.": "If a valid SSL certificate (like the panel's Let's Encrypt) is active on port 443, censorship treats the connection as a normal website visit.",
  "در لینک کانفیگ کاربر قرار می‌گیرد.": "is included in the user client configuration link.",
  "در گذشته برای ایجاد تونل امن، ملزم به خرید دامنه و دریافت سرتیفیکیت بودید. REALITY نیازی به هیچ گواهینامه‌ای ندارد؛ سرور شما در برابر اسکنرهای فعال، ادای وب‌سایت‌های CDN معتبر جهانی (نظیر": "In the past, establishing a secure tunnel required buying domains and acquiring certificates. REALITY requires zero certificates; against active scanners, your server impersonates reputable global CDN sites (such as",
  "در گذشته کلاینت ابتدا باید منتظر حل نام دامنه از سرور خارجی می‌ماند که موجب نشت اطلاعات (DNS Leak) و تاخیر می‌شد.": "Previously clients had to wait for domain resolution from foreign servers, causing DNS leaks and latency.",
  "دسته": "category",
  "دستورالعمل حیاتی پورت هاپینگ (Port Hopping):": "Critical Port Hopping Instructions:",
