  "راهنمای تنظیم بهینه پارامترها در REALITY برای اینترنت ایران:": "Optimal Parameter Configuration Guide in REALITY for Iranian Censorship:",
  "راهنمای ساخت کانفیگ": "Config Crafting Guide",
