  "ساعات افت شدید و پکت‌لاست بالا (۳۰٪ تا ۶۰٪):": "Severe degradation hours and high packet loss (30% to 60%):",
  "سبک‌ترین پروتکل": "Lightest Protocol",
  "ست کنید و رمز مبهم‌سازی Salamander را فعال نگه دارید. ترافیک شما تبدیل به نویز بدون ساختار شده و از گلوگاه‌های بازرسی عبور می‌کند.": "and keep Salamander obfuscation enabled. Your traffic morphs into unstructured noise, sliding through inspection bottlenecks.",
  "سخت‌ترین حالت تفکیک رفتاری:": "Strictest behavioral discrimination resistance:",
  "سرقت زنده هندشیک (Steal Handshake):": "Live Handshake Theft (Steal Handshake):",
  "سرور شما هیچ گواهینامه‌ای ندارد! در عوض، ادای یک سایت فوق‌معتبر خارجی (مانند dl.google.com) را بازی می‌کند.": "Your server holds no certificate! Instead, it impersonates an ultra-reputable foreign site (like dl.google.com).",
  "سرور چالش را بررسی می‌کند؛ در صورت صحت، بسته را به عنوان یک کانکشن پروکسی تحویل می‌گیرد.": "The server inspects the challenge; upon verification, it accepts the packet as a proxy connection.",
  "سریع‌ترین و سبک‌ترین ترانسپورت با حداقل مصرف حافظه RAM؛ بدون کوچک‌ترین سربار هدر پروتکل‌های وب.": "Fastest and most lightweight transport with minimal RAM usage; zero web protocol header overhead.",
  "سریع‌ترین و سبک‌ترین ترانسپورت ممکن؛ بدون هیچ سربار اضافی هدر پروتکل وب؛ تنها ترانسپورتی که از فلو فوق‌امنیتی xtls-rprx-vision پشتیبانی می‌کند.": "Fastest and most lightweight transport possible; zero web protocol header overhead; the only transport supporting the ultra-secure xtls-rprx-vision flow.",
  "سهمیه ترافیک ${pct}% مصرف شده": "Traffic quota ${pct}% consumed",
