  "فایروال با بررسی عدم تطابق IP سرور شما با ASN گوگل/مایکروسافت، پکت‌ها را فوراً فیلتر یا دستکاری می‌کند.": "Firewalls inspect IP mismatches against Google/Microsoft ASNs, immediately filtering or altering packets.",
  "فایروال به دلیل اینکه این سایت‌ها میلیاردها کاربر دارند، هرگز نمی‌تواند کل دامنه را مسدود کند!": "Because these sites serve billions of users, firewalls can never block the entire domain!",
  "فایروال‌های DPI ایران با تحلیل آماری اندازه بسته‌های اولیه TLS (بسته ClientHello و ServerHello) متوجه الگوی تونل‌های فیلترشکن می‌شوند.": "Iranian DPI firewalls analyze TLS initial packet size statistics (ClientHello & ServerHello) to fingerprint proxy tunnels.",
  "فایروال‌های سنتی پورت‌های مرسوم وب مانند ۴۴۳ را با DPI عمیق بررسی می‌کنند. پورت‌های هاپینگ متغیر اجازه می‌دهند ارتباط بدون نیاز به ثبت دامنه‌های متعدد باز بماند.": "Traditional firewalls examine standard web ports like 443 with deep packet inspection. Dynamic hopping ports keep connections alive without multiple domains.",
