  "پروتکل VMess: انعطاف‌پذیری در پشت CDN": "VMess Protocol: Flexibility Behind CDN",
  "پروتکل‌های تروجان و وی‌مس استانداردترین انتخاب‌ها برای زمانی هستند که شما دارای یک دامنه معتبر ثبت‌شده هستید یا می‌خواهید ترافیک سرور خود را از پشت سپرهای محافظتی CDN عبور دهید.": "Trojan and VMess protocols are the most standard choices when you possess a valid registered domain or wish to route server traffic behind CDN protection shields.",
  "پروتکل NaiveProxy توسط klzgrad ایجاد شد و امن‌ترین پروتکل وب‌محور جهان محسوب می‌شود. به دلیل اینکه مستقیماً از موتور شبکه رسمی مرورگر گوگل کروم بهره می‌برد، فایروال‌ها هیچ راهی برای شناسایی آن جز قطع کردن کل وبسایت‌های جهان ندارند!": "NaiveProxy was created by klzgrad and is considered the world's most secure web-centric protocol. Leveraging Google Chrome's official networking engine directly, firewalls have no means of detecting it short of blocking the entire World Wide Web!",
  "قابلیت Salamander با استفاده از یک رمز عبور اشتراکی، تمامی بسته‌های UDP را به نویزهای تصادفی و فاقد الگوی هندسی تبدیل می‌کند تا فایروال نتواند آن را به عنوان ترافیک QUIC شناسایی کند.": "Salamander capability transforms all UDP packets into random, patternless noise using a shared secret, preventing firewalls from fingerprinting it as QUIC traffic.",
  "نسخه ۲۰۲۲ پروتکل شادوساکس تمام ایرادات تاریخی نسخه‌های اولیه را برطرف کرد. این پروتکل با مشتق‌گیری کلیدها توسط الگوریتم رمزنگاری بسیار سریع BLAKE3، کمترین بار پردازشی را روی CPU سرور و دستگاه کاربر ایجاد می‌کند.": "Shadowsocks 2022 resolved all historic weaknesses of earlier iterations. Deriving keys via ultra-fast BLAKE3 cryptography, it exerts minimal compute overhead on server and client CPUs.",
  "وقتی کلاینت با آی‌پی مستقیم به سرور متصل می‌شود، هسته بدون اسنیفینگ نمی‌داند چه دامنه‌ای پشت این درخواست است.": "When clients connect to the server via direct IP, the core cannot determine the underlying domain without sniffing.",
  "هسته Sing-box با فعال‌سازی": "Sing-box core, by enabling",
  "هنگام سوئیچ کاربر میان دکل‌های اینترنت موبایل یا رفتن از وای‌فای به دیتا، کانکشن به هیچ وجه قطع نمی‌شود.": "When switching between mobile cell towers or jumping from Wi-Fi to cellular data, the connection never drops.",
  "هنگامی که کلاینت مجاز متصل می‌شود، سرور چالش را با رمز اشتراکی تایید کرده و ترافیک را تحویل می‌گیرد.": "When an authorized client connects, the server verifies the challenge using the shared secret and accepts the traffic.",
  "چرا NaiveProxy هرگز شناسایی نمی‌شود؟": "Why is NaiveProxy Never Detected?",
  "چرا Shadowsocks 2022 امن است؟": "Why is Shadowsocks 2022 Secure?",
  "چرا کلاینت هنگام استفاده از فیلترشکن دچار مسدودی حساب بانکی یا کندی سایت‌های ایرانی نمی‌شود؟ هسته Sing-box چگونه درخواست‌ها را در میلی‌ثانیه دسته‌بندی و تفکیک می‌کند؟": "Why don't clients face bank account blocking or slow Iranian websites while using the proxy? How does Sing-box core classify and split requests in milliseconds?",
